mapper.select:
SELECT invoice_no, invoice_name, invoice_is_shipped, CASE WHEN invoice_is_shipped IS NULL THEN NULL ELSE CONVERT(VARCHAR(19), insert_date, 120) END AS insert_date, CASE WHEN invoice_is_shipped IS NULL THEN NULL ELSE CONVERT(VARCHAR(19), update_date, 120) END AS update_date, invoice_is_moved, move_invoice_name FROM ez_invoice_name WHERE 1=1
AND invoice_is_shipped = #{invoice_is_shipped}
AND invoice_date >= #{startDate}
AND invoice_date <= #{endDate}
ORDER BY invoice_name DESC

SELECT 'N' AS YN_CHECK --선택 , A.CD_ITEM --품목코드 , C.NM_ITEM --품목명 , C.SPEC_ITEM --규격 , C.KGM_WEIGHT --단중 , FLOOR(ISNULL(A.LBL_REAL_LENGTH, 0)) AS LBL_REAL_LENGTH --실길이 , A.LBL_LOT_NO --라벨ID , A.NO_MFG_ORDER_SERIAL --W/O NO , FLOOR(B.QTY_INVENTORY) AS qty_inventory --재고수량 , (ISNULL(B.QTY_INVENTORY,0) * ISNULL(C.KGM_WEIGHT,0) * ISNULL(A.LBL_REAL_LENGTH,0)) / 1000 AS WGT_INVENTORY --재고중량 , B.CD_WH --창고코드 , (SELECT NM_WH FROM B_WAREHOUSE WHERE CD_WH = B.CD_WH) AS NM_WH --창고명 , A.LBL_DATE --발행일자 , A.NM_CUSTOMER --고객명 , A.PO_CUSTOMER --고객PO NO , A.NO_RECEIPT --입하NO , A.REMARKS --비고 , A.CD_WC , A.SEQ_MFG_ORDER , A.NM_LOCATION , A.ID_INSERT , A.DT_INSERT , A.ID_UPDATE , A.DT_UPDATE , eiim.invoice_no ,eiim.invoice_inventory_no ,eiim.customer_product_code_number ,eiim.extra_invoice_no ,eiim.extra_packing_inspection ,eiim.extra_order_no ,eiim.extra_part_no ,eiim.extra_spec ,eiim.extra_bundle_no ,eiim.extra_weight FROM M_WO_LABEL_DETAIL A WITH (NOLOCK) INNER JOIN I_WH_ONHAND_INVENTORY B WITH (NOLOCK) ON A.CD_ITEM = B.CD_ITEM AND A.LBL_LOT_NO = B.NO_LOT INNER JOIN B_ITEM C WITH (NOLOCK) ON A.CD_ITEM = C.CD_ITEM
INNER JOIN ez_invoice_inventory_mapping eiim ON eiim.lot_no = A.LBL_LOT_NO INNER JOIN ez_invoice_name ein ON eiim.invoice_no = ein.invoice_no INNER JOIN ez_inventory_lot_ext AS eile ON LBL_LOT_NO = eile.ext_lot_no WHERE 1=1 AND B.QTY_INVENTORY != 0 AND ein.invoice_no = #{invoice_no}
AND B.CD_WH = 'YC_FG3'

mapper.update:
INSERT INTO ez_invoice_inventory_mapping ( invoice_no, lot_no, cd_item, item_count, extra_invoice_no, extra_packing_inspection, extra_order_no, extra_part_no, extra_spec, extra_bundle_no, extra_weight, customer_product_code_number ) SELECT A.invoice_no, A.lot_no, A.cd_item, -- 기존 DB의 MAX값 + 현재 묶음 안에서의 순번 A.current_max + ROW_NUMBER() OVER(PARTITION BY A.cd_item ORDER BY A.lot_no), A.extra_invoice_no, A.extra_packing_inspection, A.extra_order_no, A.extra_part_no, A.extra_spec, A.extra_bundle_no, A.extra_weight, A.customer_product_code_number FROM (
SELECT #{invoice_no} AS invoice_no, #{item.lbl_lot_no} AS lot_no, #{item.cd_item} AS cd_item, -- 해당 품목의 현재 MAX item_count 조회 (SELECT ISNULL(MAX(item_count), 0) FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND cd_item = #{item.cd_item}) AS current_max, -- 동일한 invoice_no와 no_mfg_order_serial을 가진 기존 데이터에서 extra 값 추출 (SELECT TOP 1 extra_invoice_no FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS extra_invoice_no, (SELECT TOP 1 extra_packing_inspection FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS extra_packing_inspection, (SELECT TOP 1 extra_order_no FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS extra_order_no, (SELECT TOP 1 extra_part_no FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS extra_part_no, (SELECT TOP 1 extra_spec FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS extra_spec, (SELECT TOP 1 extra_bundle_no FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS extra_bundle_no, (SELECT TOP 1 extra_weight FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS extra_weight, (SELECT TOP 1 customer_product_code_number FROM ez_invoice_inventory_mapping WHERE invoice_no = #{invoice_no} AND lot_no IN (SELECT LBL_LOT_NO FROM M_WO_LABEL_DETAIL WHERE NO_MFG_ORDER_SERIAL = #{item.no_mfg_order_serial})) AS customer_product_code_number
) A

mapper.delete:
/* 1. 데이터 삭제 */
    DELETE FROM ez_invoice_inventory_mapping 
    WHERE invoice_no = #{invoice_no}
      AND lot_no IN

          #{lot}
      ;

    /* 2. 해당 인보이스의 전체 번호 재정렬 */
    WITH CTE AS (
        SELECT item_count,
               ROW_NUMBER() OVER (
                   PARTITION BY cd_item 
                   ORDER BY item_count, lot_no
               ) as NewCount
        FROM ez_invoice_inventory_mapping
        WHERE invoice_no = #{invoice_no}
    )
    UPDATE CTE SET item_count = NewCount;

