UPDATE S_SALES_REQUEST_PROCESS
   SET QTY_PROCESS = QTY_PROCESS + #{item.qty_inventory} + #{item.qty_bad_process}
       ,QTY_GOOD_PROCESS = QTY_GOOD_PROCESS + #{item.qty_inventory}
       ,QTY_BAD_PROCESS = QTY_BAD_PROCESS + #{item.qty_bad_process}
       ,ID_UPDATE = #{item.user_id}
       ,DT_UPDATE = GETDATE()
 WHERE NO_SALES_REQUEST_SERIAL = #{item.no_sales_request_serial}
   AND SEQ_SALES_REQUEST = #{item.seq_sales_request}
   AND FG_PROCESS = 'P'
   AND TP_PROCESS = 'INSAI'
   AND FG_MODULE = 'IN'

mapper.update:
UPDATE S_SALES_REQUEST_DETAIL SET STS_PROGRESS = CASE
WHEN QTY_STOCK_UNIT > 0 AND #{qty_process} <= 0 THEN 'R' WHEN QTY_STOCK_UNIT > 0 AND #{qty_process} > 0 AND #{qty_process} < QTY_STOCK_UNIT THEN 'P' WHEN QTY_STOCK_UNIT > 0 AND #{qty_process} >= QTY_STOCK_UNIT THEN 'F' WHEN QTY_STOCK_UNIT < 0 AND #{qty_process} >= 0 THEN 'R' WHEN QTY_STOCK_UNIT < 0 AND #{qty_process} < 0 AND #{qty_process} > QTY_STOCK_UNIT THEN 'P' WHEN QTY_STOCK_UNIT < 0 AND #{qty_process} <= QTY_STOCK_UNIT THEN 'F' ELSE STS_PROGRESS END
,ID_UPDATE = #{user_id} ,DT_UPDATE = GETDATE() WHERE NO_SALES_REQUEST_SERIAL = #{no_sales_request_serial} AND SEQ_SALES_REQUEST = #{seq_sales_request}

update.foreach:
UPDATE S_SALES_REQUEST_LOT
    SET STS_PROGRESS = 'F'
  WHERE NO_SALES_REQUEST_SERIAL = #{item.no_sales_request_serial}
    AND SEQ_SALES_REQUEST = #{item.seq_sales_request}
    AND LOT_NO = #{item.lbl_lot_no}

