mapper.select:
SELECT TOP 1 * FROM I_TRANSACTION_DETAIL
WHERE NO_LOT = #{lbl_lot_no}
ORDER BY DT_UPDATE DESC

SELECT 'N' AS YN_CHECK , A.CD_ITEM , C.NM_ITEM , C.SPEC_ITEM , C.KGM_WEIGHT , FLOOR(ISNULL(A.LBL_REAL_LENGTH, 0)) AS LBL_REAL_LENGTH , A.LBL_LOT_NO , A.NO_MFG_ORDER_SERIAL , FLOOR(B.QTY_INVENTORY) AS qty_inventory , (ISNULL(B.QTY_INVENTORY,0) * ISNULL(C.KGM_WEIGHT,0) * ISNULL(A.LBL_REAL_LENGTH,0)) / 1000 AS WGT_INVENTORY , B.CD_WH , (SELECT NM_WH FROM B_WAREHOUSE WHERE CD_WH = B.CD_WH) AS NM_WH , A.LBL_DATE , A.NM_CUSTOMER , A.PO_CUSTOMER , A.NO_RECEIPT , A.REMARKS , A.CD_WC , A.SEQ_MFG_ORDER , A.NM_LOCATION , A.ID_INSERT , A.DT_INSERT , A.ID_UPDATE , A.DT_UPDATE , NULL AS invoice_no , eiim.invoice_no , ISNULL(ein.invoice_name, '인보이스 부여되지 않음') AS invoice_name FROM M_WO_LABEL_DETAIL A WITH (NOLOCK) INNER JOIN I_WH_ONHAND_INVENTORY B WITH (NOLOCK) ON A.CD_ITEM = B.CD_ITEM AND A.LBL_LOT_NO = B.NO_LOT INNER JOIN B_ITEM C WITH (NOLOCK) ON A.CD_ITEM = C.CD_ITEM INNER JOIN ez_inventory_lot_ext AS eile ON A.LBL_LOT_NO = eile.ext_lot_no
LEFT JOIN ez_invoice_inventory_mapping eiim ON eiim.lot_no = A.LBL_LOT_NO LEFT JOIN ez_invoice_name ein ON eiim.invoice_no = ein.invoice_no WHERE B.QTY_INVENTORY != 0 AND A.LBL_LOT_NO = #{lbl_lot_no}
AND B.CD_WH = 'YC_FG3'

