-- STEP 1: scan 쪽 lot_no를 임시값으로 변경
UPDATE ez_invoice_inventory_mapping
   SET lot_no = CONCAT('__SWAP__', #{scan_lot_no})
 WHERE lot_no      = #{scan_lot_no}
   AND invoice_no  = #{scan_invoice_no};

-- STEP 2: target lot_no → scan lot_no로 변경
UPDATE ez_invoice_inventory_mapping
   SET lot_no = #{scan_lot_no}
 WHERE lot_no      = #{target_lot_no}
   AND invoice_no  = #{target_invoice_no};

-- STEP 3: 임시값 → target lot_no로 변경
UPDATE ez_invoice_inventory_mapping
   SET lot_no = #{target_lot_no}
 WHERE lot_no = CONCAT('__SWAP__', #{scan_lot_no})
   AND invoice_no = #{scan_invoice_no};

UPDATE ez_invoice_inventory_mapping
   SET lot_no = #{new_lot_no}
 WHERE lot_no     = #{old_lot_no}
   AND invoice_no = #{invoice_no}

